"""
Library Catalogue System

This module contains classes for Book, Member, and Loan management in a library.
Supports searching books, loan management, overdue detection, and fine calculation.
"""

import json
from datetime import datetime, timedelta
from typing import List, Optional


class Book:
    """Represent a book in the library catalogue."""

    def __init__(self, isbn: str, title: str, author: str, year: int, copies: int = 1):
        self.isbn = isbn
        self.title = title
        self.author = author
        self.year = year
        self.copies = copies
        self.available_copies = copies

    def __repr__(self):
        return f"<Book {self.title} by {self.author} ({self.year}), ISBN: {self.isbn}, Available: {self.available_copies}/{self.copies}>"


class Member:
    """Represent a library member."""

    def __init__(self, member_id: int, name: str, email: str):
        self.member_id = member_id
        self.name = name
        self.email = email
        self.loans = []  # List of Loan objects

    def __repr__(self):
        return f"<Member {self.name} (ID: {self.member_id})>"


class Loan:
    """Represent a loan of a book to a member."""

    def __init__(self, book: Book, member: Member, loan_date: datetime, due_days: int):
        self.book = book
        self.member = member
        self.loan_date = loan_date
        self.due_date = loan_date + timedelta(days=due_days)
        self.return_date = None

    def is_overdue(self, current_date: Optional[datetime] = None) -> bool:
        """Return True if the loan is overdue."""
        if not current_date:
            current_date = datetime.now()
        if self.return_date is None and current_date > self.due_date:
            return True
        return False

    def fine_amount(self, fine_rate: float, current_date: Optional[datetime] = None) -> float:
        """Calculate the fine based on overdue days and fine_rate."""
        if not current_date:
            current_date = datetime.now()
        if self.return_date:
            effective_date = self.return_date
        else:
            effective_date = current_date
        overdue_days = (effective_date - self.due_date).days
        if overdue_days > 0:
            return overdue_days * fine_rate
        return 0.0


class LibraryCatalogue:
    """Library Catalogue system managing books, members, and loans."""

    def __init__(self, config_path: str):
        with open(config_path, 'r') as f:
            self.config = json.load(f)

        self.books = []  # type: List[Book]
        self.members = []  # type: List[Member]
        self.loans = []  # type: List[Loan]

    def add_book(self, book: Book):
        self.books.append(book)

    def add_member(self, member: Member):
        self.members.append(member)

    def find_books_by_author(self, author_name: str) -> List[Book]:
        return [book for book in self.books if author_name.lower() in book.author.lower()]

    def find_books_by_title(self, title: str) -> List[Book]:
        return [book for book in self.books if title.lower() in book.title.lower()]

    def loan_book(self, isbn: str, member_id: int, loan_date: Optional[datetime] = None) -> Optional[Loan]:
        if loan_date is None:
            loan_date = datetime.now()
        book = next((b for b in self.books if b.isbn == isbn and b.available_copies > 0), None)
        member = next((m for m in self.members if m.member_id == member_id), None)
        if not book or not member:
            return None

        due_days = self.config.get("loan_period_days", 14)
        loan = Loan(book, member, loan_date, due_days)
        self.loans.append(loan)
        member.loans.append(loan)
        book.available_copies -= 1
        return loan

    def return_book(self, loan: Loan, return_date: Optional[datetime] = None) -> float:
        if return_date is None:
            return_date = datetime.now()
        loan.return_date = return_date
        loan.book.available_copies += 1
        fine_rate = self.config.get("fine_per_day", 1.0)
        return loan.fine_amount(fine_rate, return_date)

    def get_overdue_loans(self, current_date: Optional[datetime] = None) -> List[Loan]:
        if current_date is None:
            current_date = datetime.now()
        return [loan for loan in self.loans if loan.is_overdue(current_date)]


# End of library-catalogue system
EOF

